/// The contract shared by the server and the clients: an Orsak interface describing the side effect, its
/// provider, and the effects created from it, as Orsak.Myriad's [<GenEffects>] would write them. The proxy at the end,
/// OrderApiProxy, is generated by [<GenRemote>], when .NET builds this project; Fable compiles it as it is.
module Remoting.Shared.Contract

open System.Threading
open System.Threading.Tasks
open Orsak
open Orsak.Remoting

type OrderLine = { Product: string; Quantity: int }

type Order = {
    Customer: string
    Lines: OrderLine list
    Note: string option
}

type OrderId = OrderId of int

type PlaceError =
    | EmptyOrder
    | UnknownProduct of string

/// The side effect: ordering, wherever it happens. On the server, a real implementation; in the client, the remote one.
[<GenRemote>]
type IOrderApi =
    abstract Place: Order -> Task<Result<OrderId, PlaceError>>
    // an ASP.NET Core attribute, which MapRemote makes the endpoint's metadata, hidden from Fable, which doesn't have
    // ASP.NET Core
#if !FABLE_COMPILER
    [<Microsoft.AspNetCore.Authorization.AllowAnonymous>]
#endif
    abstract History: customer: string -> Task<Order list>
    // waits until the call is cancelled, which the client does, and Holds counts the calls held and released
    abstract Hold: cancellationToken: CancellationToken -> Task<unit>
    abstract Holds: unit -> Task<int * int>
    // counts down from a number to 1, as it streams, an effect sequence on the server: from 0 it streams the error,
    // and from below 0 the server fails after one item
    abstract Countdown: from: int -> RemoteStream<Result<int, string>>

type IOrderApiProvider =
    abstract OrderApi: IOrderApi

/// The effects, as [<GenEffects>] generates them from IOrderApi.
module OrderApi =
    let place order =
        Effect.Create(fun (p: #IOrderApiProvider) -> p.OrderApi.Place order)

    let history customer =
        Effect.Create(fun (p: #IOrderApiProvider) -> p.OrderApi.History customer)
